export async function* parseNdjson(chunks: AsyncIterable<string>): AsyncGenerator<unknown> {
  let buffer = "";
  let lineNumber = 0;
  function parseLine(line: string): unknown {
    try { return JSON.parse(line); }
    catch (error) { throw new SyntaxError("line " + lineNumber + ": invalid JSON", {cause: error}); }
  }
  for await (const chunk of chunks) {
    buffer += chunk;
    let end: number;
    while ((end = buffer.indexOf("\n")) >= 0) {
      const line = buffer.slice(0, end);
      buffer = buffer.slice(end + 1);
      lineNumber++;
      if (line.trim()) yield parseLine(line);
    }
  }
  if (buffer.length) {
    lineNumber++;
    if (buffer.trim()) yield parseLine(buffer);
  }
}
